<script setup>
import { ref, onMounted } from 'vue';
import { api } from './api';
const form=ref(null), busy=ref(false), status=ref('');
onMounted(async()=>{try{form.value={...await api('/agent/capabilities'),searchKey:''};}catch(e){status.value=e.message;}});
async function save(){busy.value=true;try{form.value={...await api('/settings/agent',{method:'PUT',body:form.value}),searchKey:''};status.value='Agent 配置已保存，下轮审查生效';}catch(e){status.value=e.message;}finally{busy.value=false;}}
async function probe(){busy.value=true;status.value='正在验证实际工具调用与连续回传…';try{const r=await api('/settings/agent/test',{method:'POST',body:{}});status.value=r.message;}catch(e){status.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="panel" style="padding:24px;margin-top:24px"><h2>Agent 运行与官方检索</h2><p>上传后自主阅读、检索和调用技能。达到限制时保存工作并暂停。</p><form v-if="form" class="stack" @submit.prevent="save"><div class="filter-row"><label>每轮请求上限<input type="number" min="2" max="200" v-model.number="form.maxRequests" required /></label><label>每轮分钟上限<input type="number" min="1" max="120" v-model.number="form.maxMinutes" required /></label><label>模型上下文容量<input type="number" min="8192" max="2000000" v-model.number="form.contextWindow" required /></label><label>最大输出 token<input type="number" min="1024" max="64000" v-model.number="form.maxOutputTokens" required /></label></div><label>推理格式<select v-model="form.thinkingFormat"><option v-for="f in ['openai','deepseek','qwen','qwen-chat-template','zai']" :key="f">{{f}}</option></select></label><label><input type="checkbox" v-model="form.reasoning" />模型支持推理参数</label><label>Brave Search API 密钥<input type="password" v-model="form.searchKey" autocomplete="new-password" :placeholder="form.hasSearchKey?'已配置，留空保留':'未配置，官网联网检索不可用'" /></label><label><input type="checkbox" v-model="form.clearSearchKey" />清除已保存的检索密钥</label><div class="action-row"><button class="primary" :disabled="busy">保存 Agent 配置</button><button type="button" :disabled="busy" @click="probe">验证工具调用与连续回传</button></div></form><p role="status">{{status}}</p></section></template>
